import CoolPropModule from '../coolprop.js';
import { promises as fs } from 'fs';
import { performance } from 'perf_hooks';

/**
 * Initialize CoolProp module
 */
async function initializeCoolProp() {
    console.log('🚀 Initializing CoolProp WASM module...');
    const startTime = performance.now();
    
    try {
        const coolprop = await CoolPropModule();
        const loadTime = performance.now() - startTime;
        
        console.log(`✅ CoolProp loaded successfully in ${loadTime.toFixed(2)} ms`);
        console.log(`📦 Module size: ${JSON.stringify(coolprop).length} characters`);
        
        return coolprop;
    } catch (error) {
        console.error('❌ Failed to initialize CoolProp:', error.message);
        throw error;
    }
}

/**
 * Example 1: Basic thermodynamic property calculations
 */
async function example1_BasicProperties(coolprop) {
    console.log('\n' + '='.repeat(60));
    console.log('📊 Example 1: Basic Thermodynamic Properties');
    console.log('='.repeat(60));
    
    try {
        // Create AbstractState for water
        const water = coolprop.factory('HEOS', 'Water');
        
        // Set state to standard conditions (1 atm, 25°C)
        const pressure = 101325; // Pa
        const temperature = 298.15; // K
        
        console.log(`\n🌡️  Setting state: P = ${pressure/1000} kPa, T = ${temperature} K`);
        
        water.update(coolprop.input_pairs.PT_INPUTS, pressure, temperature);
        
        // Calculate and display properties
        const properties = {
            'Temperature': { value: water.T(), unit: 'K', description: 'Temperature' },
            'Pressure': { value: water.p(), unit: 'Pa', description: 'Pressure' },
            'Density (molar)': { value: water.rhomolar(), unit: 'mol/m³', description: 'Molar density' },
            'Density (mass)': { value: water.rhomass(), unit: 'kg/m³', description: 'Mass density' },
            'Enthalpy (molar)': { value: water.hmolar(), unit: 'J/mol', description: 'Molar enthalpy' },
            'Enthalpy (mass)': { value: water.hmass(), unit: 'J/kg', description: 'Mass enthalpy' },
            'Entropy (molar)': { value: water.smolar(), unit: 'J/mol/K', description: 'Molar entropy' },
            'Entropy (mass)': { value: water.smass(), unit: 'J/kg/K', description: 'Mass entropy' },
            'Cp (molar)': { value: water.cpmolar(), unit: 'J/mol/K', description: 'Molar heat capacity at constant pressure' },
            'Cv (molar)': { value: water.cvmolar(), unit: 'J/mol/K', description: 'Molar heat capacity at constant volume' },
            'Speed of sound': { value: water.speed_sound(), unit: 'm/s', description: 'Speed of sound' },
            'Viscosity': { value: water.viscosity(), unit: 'Pa·s', description: 'Dynamic viscosity' },
            'Thermal conductivity': { value: water.conductivity(), unit: 'W/m/K', description: 'Thermal conductivity' },
            'Compressibility factor': { value: water.compressibility_factor(), unit: '-', description: 'Compressibility factor' }
        };
        
        console.log('\n📋 Calculated Properties:');
        console.log('-'.repeat(80));
        
        for (const [name, prop] of Object.entries(properties)) {
            const value = typeof prop.value === 'number' ? 
                (Math.abs(prop.value) > 1000 || Math.abs(prop.value) < 0.01 ? 
                 prop.value.toExponential(4) : prop.value.toFixed(6)) : 
                prop.value;
            console.log(`${name.padEnd(25)}: ${String(value).padStart(15)} ${prop.unit.padEnd(10)} | ${prop.description}`);
        }
        
        // Demonstrate phase identification
        const phase = water.phase();
        const phaseNames = ['Liquid', 'Gas', 'Two-Phase', 'Supercritical', 'Supercritical Gas', 'Supercritical Liquid', 'Critical Point'];
        console.log(`\n🔍 Phase: ${phaseNames[phase] || 'Unknown'} (${phase})`);
        
        return true;
        
    } catch (error) {
        console.error('❌ Example 1 failed:', error.message);
        return false;
    }
}

/**
 * Example 2: Saturation properties and phase transitions
 */
async function example2_SaturationProperties(coolprop) {
    console.log('\n' + '='.repeat(60));
    console.log('💧 Example 2: Saturation Properties and Phase Transitions');
    console.log('='.repeat(60));
    
    try {
        const water = coolprop.factory('HEOS', 'Water');
        
        // Calculate saturation properties at different temperatures
        const temperatures = [273.15, 300, 350, 400, 450, 500, 550, 600]; // K
        
        console.log('\n📊 Saturation Properties Table:');
        console.log('-'.repeat(100));
        console.log('T (K)'.padEnd(8) + 'P_sat (bar)'.padEnd(15) + 'ρ_liq (kg/m³)'.padEnd(15) + 'ρ_vap (kg/m³)'.padEnd(15) + 'h_fg (kJ/kg)'.padEnd(15) + 's_fg (kJ/kg/K)');
        console.log('-'.repeat(100));
        
        for (const T of temperatures) {
            try {
                // Saturated liquid properties
                water.update(coolprop.input_pairs.QT_INPUTS, 0, T);
                const pSat = water.p();
                const rhoLiq = water.rhomass();
                const hLiq = water.hmass();
                const sLiq = water.smass();
                
                // Saturated vapor properties
                water.update(coolprop.input_pairs.QT_INPUTS, 1, T);
                const rhoVap = water.rhomass();
                const hVap = water.hmass();
                const sVap = water.smass();
                
                // Calculate latent properties
                const hfg = (hVap - hLiq) / 1000; // kJ/kg
                const sfg = (sVap - sLiq) / 1000; // kJ/kg/K
                
                console.log(
                    T.toFixed(1).padEnd(8) +
                    (pSat / 1e5).toFixed(3).padEnd(15) +
                    rhoLiq.toFixed(1).padEnd(15) +
                    rhoVap.toFixed(4).padEnd(15) +
                    hfg.toFixed(1).padEnd(15) +
                    sfg.toFixed(4)
                );
                
            } catch (error) {
                console.log(`${T.toFixed(1).padEnd(8)}${'Error'.padEnd(15)}${'---'.padEnd(15)}${'---'.padEnd(15)}${'---'.padEnd(15)}---`);
            }
        }
        
        // Demonstrate two-phase calculations
        console.log('\n🌡️  Two-Phase Property Calculations at 100°C:');
        console.log('-'.repeat(60));
        
        const qualities = [0, 0.1, 0.25, 0.5, 0.75, 0.9, 1.0];
        
        console.log('Quality'.padEnd(10) + 'Density (kg/m³)'.padEnd(18) + 'Enthalpy (kJ/kg)'.padEnd(18) + 'Entropy (kJ/kg/K)');
        console.log('-'.repeat(60));
        
        for (const Q of qualities) {
            water.update(coolprop.input_pairs.QT_INPUTS, Q, 373.15);
            
            const density = water.rhomass();
            const enthalpy = water.hmass() / 1000; // kJ/kg
            const entropy = water.smass() / 1000; // kJ/kg/K
            
            console.log(
                Q.toFixed(1).padEnd(10) +
                density.toFixed(2).padEnd(18) +
                enthalpy.toFixed(1).padEnd(18) +
                entropy.toFixed(4)
            );
        }
        
        return true;
        
    } catch (error) {
        console.error('❌ Example 2 failed:', error.message);
        return false;
    }
}

/**
 * Example 3: Mixture calculations
 */
async function example3_MixtureCalculations(coolprop) {
    console.log('\n' + '='.repeat(60));
    console.log('🧪 Example 3: Mixture Calculations');
    console.log('='.repeat(60));
    
    try {
        // Natural gas mixture (simplified)
        console.log('\n⛽ Natural Gas Mixture Analysis:');
        
        const mixture = coolprop.factory('HEOS', 'Methane&Ethane&Propane&n-Butane');
        const composition = [0.85, 0.10, 0.04, 0.01]; // Mole fractions
        
        // Create VectorDouble for mole fractions
        const moleFractions = new coolprop.VectorDouble();
        for (const fraction of composition) {
            moleFractions.push_back(fraction);
        }
        
        mixture.set_mole_fractions(moleFractions);
        
        console.log('📋 Composition:');
        const components = ['Methane', 'Ethane', 'Propane', 'n-Butane'];
        for (let i = 0; i < components.length; i++) {
            console.log(`   ${components[i]}: ${(composition[i] * 100).toFixed(1)}%`);
        }
        
        // Calculate properties at different conditions
        const conditions = [
            { P: 1e5, T: 288.15, desc: 'Standard conditions (1 bar, 15°C)' },
            { P: 5e6, T: 273.15, desc: 'Pipeline conditions (50 bar, 0°C)' },
            { P: 20e6, T: 253.15, desc: 'High pressure (200 bar, -20°C)' }
        ];
        
        console.log('\n📊 Mixture Properties at Different Conditions:');
        console.log('-'.repeat(90));
        console.log('Condition'.padEnd(35) + 'Density (kg/m³)'.padEnd(18) + 'Z-factor'.padEnd(12) + 'Cp (kJ/kg/K)'.padEnd(15) + 'MW (g/mol)');
        console.log('-'.repeat(90));
        
        for (const condition of conditions) {
            try {
                mixture.update(coolprop.input_pairs.PT_INPUTS, condition.P, condition.T);
                
                const density = mixture.rhomass();
                const zFactor = mixture.compressibility_factor();
                const cp = mixture.cpmass() / 1000; // kJ/kg/K
                const molarMass = mixture.molar_mass() * 1000; // g/mol
                
                console.log(
                    condition.desc.padEnd(35) +
                    density.toFixed(2).padEnd(18) +
                    zFactor.toFixed(4).padEnd(12) +
                    cp.toFixed(3).padEnd(15) +
                    molarMass.toFixed(2)
                );
                
            } catch (error) {
                console.log(`${condition.desc.padEnd(35)}${'Error'.padEnd(18)}---`.padEnd(12) + '---'.padEnd(15) + '---');
            }
        }
        
        // Demonstrate phase envelope calculation (if available)
        try {
            console.log('\n🌡️  Phase Envelope Calculation:');
            mixture.build_phase_envelope('');
            const envelope = mixture.get_phase_envelope_data();
            
            if (envelope && envelope.T && envelope.T.length > 0) {
                console.log(`   ✅ Phase envelope calculated with ${envelope.T.length} points`);
                console.log(`   🌡️  Temperature range: ${Math.min(...envelope.T).toFixed(1)} - ${Math.max(...envelope.T).toFixed(1)} K`);
                console.log(`   📊 Pressure range: ${(Math.min(...envelope.p) / 1e5).toFixed(1)} - ${(Math.max(...envelope.p) / 1e5).toFixed(1)} bar`);
            } else {
                console.log('   ⚠️  Phase envelope data not available');
            }
        } catch (error) {
            console.log(`   ❌ Phase envelope calculation failed: ${error.message}`);
        }
        
        return true;
        
    } catch (error) {
        console.error('❌ Example 3 failed:', error.message);
        return false;
    }
}

/**
 * Example 4: Derivative calculations and thermodynamic relations
 */
async function example4_DerivativeCalculations(coolprop) {
    console.log('\n' + '='.repeat(60));
    console.log('📐 Example 4: Derivative Calculations and Thermodynamic Relations');
    console.log('='.repeat(60));
    
    try {
        const co2 = coolprop.factory('HEOS', 'CO2');
        
        // Set state to supercritical conditions
        const pressure = 10e6; // 100 bar
        const temperature = 350; // K
        
        co2.update(coolprop.input_pairs.PT_INPUTS, pressure, temperature);
        
        console.log(`\n🌡️  State: P = ${pressure/1e6} MPa, T = ${temperature} K`);
        console.log(`📊 Phase: Supercritical (Z = ${co2.compressibility_factor().toFixed(4)})`);
        
        // Calculate various partial derivatives
        console.log('\n📐 Partial Derivatives:');
        console.log('-'.repeat(70));
        
        const derivatives = [
            {
                name: 'dP/dT|ρ',
                of: coolprop.parameters.iP,
                wrt: coolprop.parameters.iT,
                constant: coolprop.parameters.iDmolar,
                unit: 'Pa/K',
                description: 'Pressure derivative with respect to temperature at constant density'
            },
            {
                name: 'dP/dρ|T',
                of: coolprop.parameters.iP,
                wrt: coolprop.parameters.iDmolar,
                constant: coolprop.parameters.iT,
                unit: 'Pa·m³/mol',
                description: 'Pressure derivative with respect to density at constant temperature'
            },
            {
                name: 'dH/dT|P',
                of: coolprop.parameters.iHmolar,
                wrt: coolprop.parameters.iT,
                constant: coolprop.parameters.iP,
                unit: 'J/mol/K',
                description: 'Enthalpy derivative (should equal Cp)'
            },
            {
                name: 'dS/dP|T',
                of: coolprop.parameters.iSmolar,
                wrt: coolprop.parameters.iP,
                constant: coolprop.parameters.iT,
                unit: 'J/mol/K/Pa',
                description: 'Entropy derivative with respect to pressure'
            }
        ];
        
        for (const deriv of derivatives) {
            try {
                const value = co2.first_partial_deriv(deriv.of, deriv.wrt, deriv.constant);
                const formattedValue = Math.abs(value) > 1000 || Math.abs(value) < 0.01 ? 
                    value.toExponential(4) : value.toFixed(6);
                
                console.log(`${deriv.name.padEnd(12)}: ${formattedValue.padStart(15)} ${deriv.unit.padEnd(15)} | ${deriv.description}`);
            } catch (error) {
                console.log(`${deriv.name.padEnd(12)}: ${'Error'.padStart(15)} ${deriv.unit.padEnd(15)} | ${deriv.description}`);
            }
        }
        
        // Verify thermodynamic relations
        console.log('\n🔍 Thermodynamic Relation Verification:');
        console.log('-'.repeat(50));
        
        try {
            const cp = co2.cpmolar();
            const dH_dT_p = co2.first_partial_deriv(coolprop.parameters.iHmolar, coolprop.parameters.iT, coolprop.parameters.iP);
            const cpDifference = Math.abs(cp - dH_dT_p);
            
            console.log(`Cp (direct):           ${cp.toFixed(3)} J/mol/K`);
            console.log(`dH/dT|P (derivative):  ${dH_dT_p.toFixed(3)} J/mol/K`);
            console.log(`Difference:            ${cpDifference.toFixed(6)} J/mol/K`);
            console.log(`Verification:          ${cpDifference < 1e-6 ? '✅ PASS' : '❌ FAIL'}`);
            
        } catch (error) {
            console.log(`Cp verification failed: ${error.message}`);
        }
        
        // Calculate second derivatives (if available)
        console.log('\n📐 Second Derivatives:');
        console.log('-'.repeat(50));
        
        try {
            const d2P_dT2 = co2.second_partial_deriv(
                coolprop.parameters.iP, 
                coolprop.parameters.iT, 
                coolprop.parameters.iDmolar,
                coolprop.parameters.iT, 
                coolprop.parameters.iDmolar
            );
            console.log(`d²P/dT²|ρ:             ${d2P_dT2.toExponential(4)} Pa/K²`);
        } catch (error) {
            console.log(`Second derivative calculation: ${error.message}`);
        }
        
        return true;
        
    } catch (error) {
        console.error('❌ Example 4 failed:', error.message);
        return false;
    }
}

/**
 * Example 5: Critical and limiting properties
 */
async function example5_CriticalProperties(coolprop) {
    console.log('\n' + '='.repeat(60));
    console.log('🎯 Example 5: Critical and Limiting Properties');
    console.log('='.repeat(60));
    
    try {
        const fluids = ['Water', 'CO2', 'Nitrogen', 'Propane', 'R134a', 'Ammonia'];
        
        console.log('\n📊 Critical Properties Comparison:');
        console.log('-'.repeat(100));
        console.log('Fluid'.padEnd(12) + 'Tc (K)'.padEnd(12) + 'Pc (MPa)'.padEnd(12) + 'ρc (kg/m³)'.padEnd(15) + 'MW (g/mol)'.padEnd(12) + 'ω (-)'.padEnd(10) + 'Tmin (K)');
        console.log('-'.repeat(100));
        
        for (const fluidName of fluids) {
            try {
                const fluid = coolprop.factory('HEOS', fluidName);
                
                const Tc = fluid.T_critical();
                const Pc = fluid.p_critical() / 1e6; // MPa
                const rhoc = fluid.rhomass_critical();
                const MW = fluid.molar_mass() * 1000; // g/mol
                const Tmin = fluid.Tmin();
                
                let omega = 'N/A';
                try {
                    omega = fluid.acentric_factor().toFixed(4);
                } catch {
                    // Acentric factor not available for all fluids
                }
                
                console.log(
                    fluidName.padEnd(12) +
                    Tc.toFixed(2).padEnd(12) +
                    Pc.toFixed(3).padEnd(12) +
                    rhoc.toFixed(1).padEnd(15) +
                    MW.toFixed(2).padEnd(12) +
                    String(omega).padEnd(10) +
                    Tmin.toFixed(1)
                );
                
            } catch (error) {
                console.log(`${fluidName.padEnd(12)}${'Error'.padEnd(12)}---`.padEnd(12) + '---'.padEnd(15) + '---'.padEnd(12) + '---'.padEnd(10) + '---');
            }
        }
        
        // Demonstrate reduced properties
        console.log('\n🌡️  Reduced Properties Analysis for Water:');
        console.log('-'.repeat(60));
        
        const water = coolprop.factory('HEOS', 'Water');
        const Tc = water.T_critical();
        const Pc = water.p_critical();
        const rhoc = water.rhomass_critical();
        
        const conditions = [
            { T: 298.15, P: 101325, desc: 'Ambient conditions' },
            { T: 373.15, P: 101325, desc: 'Boiling point (1 atm)' },
            { T: 500, P: 5e6, desc: 'Subcritical steam' },
            { T: 700, P: 30e6, desc: 'Supercritical steam' }
        ];
        
        console.log('Condition'.padEnd(25) + 'Tr (-)'.padEnd(10) + 'Pr (-)'.padEnd(10) + 'ρr (-)'.padEnd(10) + 'Phase');
        console.log('-'.repeat(60));
        
        for (const condition of conditions) {
            try {
                water.update(coolprop.input_pairs.PT_INPUTS, condition.P, condition.T);
                
                const Tr = condition.T / Tc;
                const Pr = condition.P / Pc;
                const rhor = water.rhomass() / rhoc;
                const phase = water.phase();
                const phaseNames = ['Liquid', 'Gas', 'Two-Phase', 'Supercritical'];
                
                console.log(
                    condition.desc.padEnd(25) +
                    Tr.toFixed(3).padEnd(10) +
                    Pr.toFixed(3).padEnd(10) +
                    rhor.toFixed(3).padEnd(10) +
                    (phaseNames[phase] || 'Unknown')
                );
                
            } catch (error) {
                console.log(`${condition.desc.padEnd(25)}${'Error'.padEnd(10)}---`.padEnd(10) + '---'.padEnd(10) + 'Error');
            }
        }
        
        return true;
        
    } catch (error) {
        console.error('❌ Example 5 failed:', error.message);
        return false;
    }
}

/**
 * Example 6: Performance benchmarking
 */
async function example6_PerformanceBenchmarking(coolprop) {
    console.log('\n' + '='.repeat(60));
    console.log('⚡ Example 6: Performance Benchmarking');
    console.log('='.repeat(60));
    
    try {
        const iterations = 1000;
        
        console.log(`\n🏃 Running performance benchmarks (${iterations} iterations)...`);
        
        // Benchmark 1: State creation
        console.log('\n📊 Benchmark 1: AbstractState Creation');
        const createTimes = [];
        
        for (let i = 0; i < iterations; i++) {
            const start = performance.now();
            const state = coolprop.factory('HEOS', 'Water');
            createTimes.push(performance.now() - start);
        }
        
        const avgCreateTime = createTimes.reduce((a, b) => a + b, 0) / createTimes.length;
        const minCreateTime = Math.min(...createTimes);
        const maxCreateTime = Math.max(...createTimes);
        
        console.log(`   Average: ${avgCreateTime.toFixed(4)} ms`);
        console.log(`   Min:     ${minCreateTime.toFixed(4)} ms`);
        console.log(`   Max:     ${maxCreateTime.toFixed(4)} ms`);
        console.log(`   Rate:    ${(1000 / avgCreateTime).toFixed(0)} creations/second`);
        
        // Benchmark 2: Property calculations
        console.log('\n📊 Benchmark 2: Property Calculations');
        const water = coolprop.factory('HEOS', 'Water');
        water.update(coolprop.input_pairs.PT_INPUTS, 101325, 300);
        
        const propTimes = [];
        
        for (let i = 0; i < iterations; i++) {
            const start = performance.now();
            const T = water.T();
            const P = water.p();
            const rho = water.rhomolar();
            const h = water.hmolar();
            const s = water.smolar();
            propTimes.push(performance.now() - start);
        }
        
        const avgPropTime = propTimes.reduce((a, b) => a + b, 0) / propTimes.length;
        const minPropTime = Math.min(...propTimes);
        const maxPropTime = Math.max(...propTimes);
        
        console.log(`   Average: ${avgPropTime.toFixed(4)} ms`);
        console.log(`   Min:     ${minPropTime.toFixed(4)} ms`);
        console.log(`   Max:     ${maxPropTime.toFixed(4)} ms`);
        console.log(`   Rate:    ${(1000 / avgPropTime).toFixed(0)} calculations/second`);
        
        // Benchmark 3: State updates
        console.log('\n📊 Benchmark 3: State Updates');
        const updateTimes = [];
        
        for (let i = 0; i < iterations; i++) {
            const start = performance.now();
            water.update(coolprop.input_pairs.PT_INPUTS, 101325 + i, 300 + i * 0.1);
            updateTimes.push(performance.now() - start);
        }
        
        const avgUpdateTime = updateTimes.reduce((a, b) => a + b, 0) / updateTimes.length;
        const minUpdateTime = Math.min(...updateTimes);
        const maxUpdateTime = Math.max(...updateTimes);
        
        console.log(`   Average: ${avgUpdateTime.toFixed(4)} ms`);
        console.log(`   Min:     ${minUpdateTime.toFixed(4)} ms`);
        console.log(`   Max:     ${maxUpdateTime.toFixed(4)} ms`);
        console.log(`   Rate:    ${(1000 / avgUpdateTime).toFixed(0)} updates/second`);
        
        // Memory usage (if available)
        if (process.memoryUsage) {
            console.log('\n💾 Memory Usage:');
            const memUsage = process.memoryUsage();
            console.log(`   RSS:          ${(memUsage.rss / 1024 / 1024).toFixed(2)} MB`);
            console.log(`   Heap Total:   ${(memUsage.heapTotal / 1024 / 1024).toFixed(2)} MB`);
            console.log(`   Heap Used:    ${(memUsage.heapUsed / 1024 / 1024).toFixed(2)} MB`);
            console.log(`   External:     ${(memUsage.external / 1024 / 1024).toFixed(2)} MB`);
        }
        
        // Performance summary
        console.log('\n📈 Performance Summary:');
        console.log('-'.repeat(40));
        const totalTime = avgCreateTime + avgUpdateTime + avgPropTime;
        console.log(`Total calculation time: ${totalTime.toFixed(4)} ms`);
        console.log(`Throughput:            ${(1000 / totalTime).toFixed(0)} complete cycles/second`);
        
        // Performance rating
        let rating = 'Unknown';
        if (totalTime < 1) rating = '🚀 Excellent';
        else if (totalTime < 5) rating = '✅ Good';
        else if (totalTime < 20) rating = '⚠️  Acceptable';
        else rating = '❌ Slow';
        
        console.log(`Performance rating:    ${rating}`);
        
        return true;
        
    } catch (error) {
        console.error('❌ Example 6 failed:', error.message);
        return false;
    }
}

/**
 * Example 7: Data export and file operations
 */
async function example7_DataExport(coolprop) {
    console.log('\n' + '='.repeat(60));
    console.log('💾 Example 7: Data Export and File Operations');
    console.log('='.repeat(60));
    
    try {
        // Generate saturation data for water
        console.log('\n📊 Generating saturation data for water...');
        
        const water = coolprop.factory('HEOS', 'Water');
        const Tc = water.T_critical();
        
        // Generate temperature range
        const temperatures = [];
        const step = (Tc - 273.15) / 50; // 50 points from 0°C to critical temperature
        
        for (let T = 273.15; T < Tc; T += step) {
            temperatures.push(T);
        }
        
        // Calculate saturation properties
        const saturationData = [];
        
        for (const T of temperatures) {
            try {
                // Liquid properties
                water.update(coolprop.input_pairs.QT_INPUTS, 0, T);
                const pSat = water.p();
                const rhoLiq = water.rhomass();
                const hLiq = water.hmass();
                const sLiq = water.smass();
                
                // Vapor properties
                water.update(coolprop.input_pairs.QT_INPUTS, 1, T);
                const rhoVap = water.rhomass();
                const hVap = water.hmass();
                const sVap = water.smass();
                
                saturationData.push({
                    temperature: T,
                    pressure: pSat,
                    densityLiquid: rhoLiq,
                    densityVapor: rhoVap,
                    enthalpyLiquid: hLiq,
                    enthalpyVapor: hVap,
                    entropyLiquid: sLiq,
                    entropyVapor: sVap,
                    enthalpyVaporization: hVap - hLiq,
                    entropyVaporization: sVap - sLiq
                });
                
            } catch (error) {
                // Skip problematic points near critical temperature
                continue;
            }
        }
        
        console.log(`✅ Generated ${saturationData.length} data points`);
        
        // Export to CSV
        console.log('\n💾 Exporting to CSV format...');
        
        let csvContent = 'Temperature (K),Pressure (Pa),Density Liquid (kg/m³),Density Vapor (kg/m³),';
        csvContent += 'Enthalpy Liquid (J/kg),Enthalpy Vapor (J/kg),Entropy Liquid (J/kg/K),Entropy Vapor (J/kg/K),';
        csvContent += 'Enthalpy of Vaporization (J/kg),Entropy of Vaporization (J/kg/K)\n';
        
        for (const point of saturationData) {
            csvContent += `${point.temperature.toFixed(2)},${point.pressure.toFixed(1)},`;
            csvContent += `${point.densityLiquid.toFixed(2)},${point.densityVapor.toFixed(6)},`;
            csvContent += `${point.enthalpyLiquid.toFixed(1)},${point.enthalpyVapor.toFixed(1)},`;
            csvContent += `${point.entropyLiquid.toFixed(2)},${point.entropyVapor.toFixed(2)},`;
            csvContent += `${point.enthalpyVaporization.toFixed(1)},${point.entropyVaporization.toFixed(4)}\n`;
        }
        
        // Write to file
        const filename = 'water_saturation_properties.csv';
        await fs.writeFile(filename, csvContent);
        console.log(`✅ Data exported to ${filename}`);
        
        // Export to JSON
        console.log('\n💾 Exporting to JSON format...');
        
        const jsonData = {
            metadata: {
                fluid: 'Water',
                backend: 'HEOS',
                generatedAt: new Date().toISOString(),
                dataPoints: saturationData.length,
                temperatureRange: {
                    min: Math.min(...saturationData.map(p => p.temperature)),
                    max: Math.max(...saturationData.map(p => p.temperature)),
                    unit: 'K'
                }
            },
            data: saturationData
        };
        
        const jsonFilename = 'water_saturation_properties.json';
        await fs.writeFile(jsonFilename, JSON.stringify(jsonData, null, 2));
        console.log(`✅ Data exported to ${jsonFilename}`);
        
        // Generate summary statistics
        console.log('\n📊 Data Summary:');
        console.log('-'.repeat(50));
        
        const pressures = saturationData.map(p => p.pressure);
        const hfg = saturationData.map(p => p.enthalpyVaporization);
        
        console.log(`Temperature range:     ${Math.min(...saturationData.map(p => p.temperature)).toFixed(1)} - ${Math.max(...saturationData.map(p => p.temperature)).toFixed(1)} K`);
        console.log(`Pressure range:        ${(Math.min(...pressures) / 1000).toFixed(1)} - ${(Math.max(...pressures) / 1e6).toFixed(1)} kPa - MPa`);
        console.log(`Max h_fg:              ${(Math.max(...hfg) / 1000).toFixed(1)} kJ/kg`);
        console.log(`Min h_fg:              ${(Math.min(...hfg) / 1000).toFixed(1)} kJ/kg`);
        
        return true;
        
    } catch (error) {
        console.error('❌ Example 7 failed:', error.message);
        return false;
    }
}

/**
 * Main function to run all examples
 */
async function runAllExamples() {
    console.log('🌟 CoolProp WASM Node.js Examples');
    console.log('='.repeat(80));
    console.log('Comprehensive demonstration of thermodynamic calculations using CoolProp WASM');
    console.log('='.repeat(80));
    
    const startTime = performance.now();
    let successCount = 0;
    let totalExamples = 0;
    
    try {
        // Initialize CoolProp
        const coolprop = await initializeCoolProp();
        
        // Run all examples
        const examples = [
            { name: 'Basic Properties', func: example1_BasicProperties },
            { name: 'Saturation Properties', func: example2_SaturationProperties },
            { name: 'Mixture Calculations', func: example3_MixtureCalculations },
            { name: 'Derivative Calculations', func: example4_DerivativeCalculations },
            { name: 'Critical Properties', func: example5_CriticalProperties },
            { name: 'Performance Benchmarking', func: example6_PerformanceBenchmarking },
            { name: 'Data Export', func: example7_DataExport }
        ];
        
        for (const example of examples) {
            totalExamples++;
            console.log(`\n🔄 Running ${example.name}...`);
            
            try {
                const success = await example.func(coolprop);
                if (success) {
                    successCount++;
                    console.log(`✅ ${example.name} completed successfully`);
                } else {
                    console.log(`❌ ${example.name} failed`);
                }
            } catch (error) {
                console.error(`❌ ${example.name} threw an error:`, error.message);
            }
        }
        
    } catch (error) {
        console.error('❌ Failed to initialize CoolProp:', error.message);
        process.exit(1);
    }
    
    const endTime = performance.now();
    const totalTime = (endTime - startTime) / 1000;
    
    // Print final summary
    console.log('\n' + '='.repeat(80));
    console.log('📋 EXECUTION SUMMARY');
    console.log('='.repeat(80));
    console.log(`Total examples:        ${totalExamples}`);
    console.log(`Successful:           ${successCount}`);
    console.log(`Failed:               ${totalExamples - successCount}`);
    console.log(`Success rate:         ${((successCount / totalExamples) * 100).toFixed(1)}%`);
    console.log(`Total execution time: ${totalTime.toFixed(2)} seconds`);
    console.log(`Average per example:  ${(totalTime / totalExamples).toFixed(2)} seconds`);
    
    if (successCount === totalExamples) {
        console.log('\n🎉 All examples completed successfully!');
        console.log('📁 Check the generated CSV and JSON files for exported data.');
        process.exit(0);
    } else {
        console.log('\n⚠️  Some examples failed. Check the output above for details.');
        process.exit(1);
    }
}

// Export functions for use in other modules
export {
    initializeCoolProp,
    example1_BasicProperties,
    example2_SaturationProperties,
    example3_MixtureCalculations,
    example4_DerivativeCalculations,
    example5_CriticalProperties,
    example6_PerformanceBenchmarking,
    example7_DataExport,
    runAllExamples
};

// Run examples if this file is executed directly
if (import.meta.url === `file://${process.argv[1]}`) {
    runAllExamples().catch(console.error);
}